<?php
$control=order_admin_state((int)$order['id']);$actionContract=one('SELECT * FROM shop_contracts WHERE order_id=?',[$order['id']]);$closed=contract_closed($actionContract) || in_array($order['fulfillment_status'],['cancelled','ended'],true);
$manualProviderDone=admin_provider_manually_ended($actionContract);$manualCompletionAvailable=$closed && !$manualProviderDone && $actionContract && ($actionContract['end_state']!=='done' || $actionContract['paypal_cancel_state']!=='done');
$deleted=!empty($control['deleted_ts']);$readyToDelete=$closed;foreach(admin_order_family($order) as $related)if(!admin_order_can_delete($related))$readyToDelete=false;
?>
<section class="panel form-panel order-admin-actions" aria-labelledby="order-actions-heading">
    <h2 id="order-actions-heading"><?= !empty($contractActionContext)?'Vertragsaktionen':'Bestellung verwalten' ?></h2>
    <?php if($deleted): ?><div class="info-box"><?= icon('lock') ?><span>Diese Bestellung wurde am <?= date('d.m.Y H:i',(int)$control['deleted_ts']) ?> aus der Übersicht gelöscht. Rechnungen, Zahlungen und Vertragsnachweise bleiben erhalten.</span></div>
    <?php elseif($manualProviderDone): ?><div class="info-box"><?= icon('check') ?><span>Die technische Beendigung wurde durch die Administration manuell abgeschlossen. <?= $readyToDelete?'PayPal-Abschluss ebenfalls erledigt; die Bestellung kann ohne weiteren Worker-Lauf aus der Übersicht gelöscht werden.':'Der PayPal-Abschluss ist noch offen und kann im Vertrag direkt geprüft werden.' ?></span></div>
    <?php elseif(!empty($control['cancelled_ts'])): ?><div class="info-box"><?= icon('clock') ?><span>Am <?= date('d.m.Y H:i',(int)$control['cancelled_ts']) ?> durch die Administration storniert. <?= $readyToDelete?'Anbieter- und PayPal-Beendigung sind abgeschlossen.':'Der Hintergrunddienst schließt die Anbieter- und PayPal-Beendigung ab. Hinweise dazu findest du unter Verträge & Kündigungen.' ?></span></div>
    <?php elseif(!empty($control['activated_ts'])): ?><div class="info-box"><?= icon('check') ?><span>Manuelle Freigabe vom <?= date('d.m.Y H:i',(int)$control['activated_ts']) ?>. Der Zahlungsstatus wurde dabei nicht verändert. Offene Rechnungen müssen weiterhin beglichen werden.</span></div><?php endif ?>
    <?php $available=$deleted?['restore'=>['Bestellung wiederherstellen','Nur wieder in der Bestellübersicht anzeigen. Der beendete Vertrag wird nicht erneut aktiviert.']]:array_filter(['activate'=>!$closed && empty($actionContract['cancel_at']) && in_array($order['payment_status'],['pending','paid','test_paid','no_charge'],true) && $order['fulfillment_status']!=='active'?['Manuell aktivieren','Die Einrichtung beim Anbieter unabhängig vom Zahlungsstatus freigeben. Das Paket wird erst nach erfolgreicher Einrichtung aktiv. Bei einem unklaren Anbieterauftrag zuerst die vorhandene Ressource zuordnen.']:null,'cancel'=>(!$closed || $manualCompletionAvailable)?[$manualCompletionAvailable?'Manuelle Beendigung abschließen':(!empty($contractActionContext)?'Jetzt sofort kündigen':'Bestellung stornieren'),'Vertrag und Zusatzmodule im Shop sofort beenden. Die zugehörigen Systeme werden durch Sie von Hand beendet oder entfernt; dieser Abschluss wird direkt dokumentiert. PayPal-Abos werden separat direkt per API beendet und geprüft. Bereits geleistete Zahlungen werden nicht automatisch erstattet.']:null,'delete'=>['Bestellung löschen','Aus der Bestellübersicht entfernen. Rechnungen, Zahlungen und Vertragsnachweise bleiben erhalten. Die Bestellung und ihre Zusatzmodule müssen vorher vollständig beendet sein.']]);if(!empty($contractActionContext))$available=array_intersect_key($available,array_flip($manualProviderDone && $readyToDelete?['activate','cancel','delete']:['activate','cancel']));foreach($available as $operation=>[$caption,$description]): ?>
    <details class="order-admin-operation <?= !empty($contractActionContext) && $operation==='cancel'?'contract-end-now-operation':'' ?>" <?= !empty($contractActionContext) && $operation==='cancel'?'id="vertrag-sofort-beenden" open':'' ?>><summary><?= !empty($contractActionContext) && $operation==='cancel'?'Vertrag sofort beenden':e($caption) ?></summary><p><?= e($description) ?></p>
        <?php if(!empty($contractActionContext) && $operation==='cancel'): ?><div class="info-box"><?= icon('clock') ?><span><strong>Das Vertragsende wird auf jetzt gesetzt.</strong> Ein bereits vorgemerkter späterer Kündigungstermin wird vorgezogen. Die technische Beendigung gilt mit Ihrer Bestätigung als manuell abgeschlossen. Der Shop startet dafür keine Abschaltung, Sicherung oder Löschung beim Anbieter. PayPal-Abos werden direkt über die API beendet und geprüft.</span></div><?php endif ?>
        <?php if($operation==='delete' && !$readyToDelete): ?><p class="muted">Löschen ist erst nach abgeschlossener Stornierung und Anbieter-/PayPal-Beendigung möglich. <a class="text-link" href="/admin/vertraege">Vertragsstatus ansehen</a></p>
        <?php else: ?>
        <form method="post" data-confirm="<?= e($caption) ?>? <?= $operation==='cancel'?'Die manuelle Beendigung wird im Shop dokumentiert. PayPal-Abos werden direkt beendet.':($operation==='activate'?'Die Einrichtung wird auch ohne Zahlung freigegeben.':'') ?>"><?= csrf() ?><input type="hidden" name="action" value="admin_order_<?= $operation ?>"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="return_to" value="<?= !empty($contractActionContext)?'contracts':'orders' ?>"><input type="hidden" name="operation_token" value="<?= bin2hex(random_bytes(32)) ?>">
            <label class="field"><span>Begründung</span><textarea name="reason" rows="3" minlength="3" maxlength="1000" required></textarea></label>
            <?php if($operation==='activate'): ?>
            <?php if($order['provider']==='manual'): ?><label class="field"><span>Bereitgestellte Leistungskennung / Projektname</span><input name="identifier" maxlength="253" value="<?= e($order['domain']) ?>" required></label><?php endif ?>
            <label class="checkbox-field"><input type="checkbox" name="unpaid_release_confirmed" value="1" required><span>Ich gebe die Einrichtung ausdrücklich auch ohne bestätigten Zahlungseingang frei. Offene Rechnungen bleiben offen.</span></label>
            <?php if($order['provider']==='ovh' && !order_payment_allows_provisioning($order)): ?><label class="checkbox-field"><input type="checkbox" name="supplier_costs_confirmed" value="1" required><span>Ich übernehme die bei OVH anfallenden Kosten der Domainregistrierung unabhängig von der Kundenzahlung.</span></label><?php endif ?>
            <?php endif ?>
            <label class="checkbox-field"><input type="checkbox" name="confirmed" value="1" required><span><?= $operation==='cancel'?'Ich habe die zugehörigen Systeme und Moduländerungen selbst beendet oder entfernt und bestätige den sofortigen Vertragsabschluss im Shop.':'Ich bestätige diese Bestellaktion und die dokumentierte Begründung.' ?></span></label><button class="button <?= $operation==='activate'?'button-teal':'button-outline' ?>" type="submit"><?= e($caption) ?></button>
        </form>
        <?php endif ?>
    </details>
    <?php endforeach ?>
    <?php $history=all('SELECT e.*,u.username FROM shop_order_admin_events e LEFT JOIN users u ON u.id=e.admin_id WHERE e.order_id=? ORDER BY e.id DESC LIMIT 20',[$order['id']]);if($history): ?>
    <details class="order-admin-operation"><summary>Protokoll der Bestellaktionen</summary><dl class="detail-list"><?php foreach($history as $event): ?><div><dt><?= date('d.m.Y H:i',(int)$event['created_ts']) ?> · <?= e($event['username']??'Administrator') ?></dt><dd><strong><?= e(['activate'=>'Manuell freigegeben','cancel'=>'Storniert','cancel_term'=>'Zum Laufzeitende gekündigt','delete'=>'Gelöscht','restore'=>'Wiederhergestellt'][$event['operation']]??$event['operation']) ?></strong><br><?= e($event['reason']) ?></dd></div><?php endforeach ?></dl></details>
    <?php endif ?>
</section>
